// 3D Sphere Distortion Effect
// Non-Shadertoy format with uniforms, v_uv, fragColor

//@slider min=0.0 max=1.0 value=0.3
uniform float spherize_radius;

//@slider min=-2.0 max=2.0 value=1.0
uniform float spherize_strength;

//@slider min=0.0 max=1.0 value=0.5
uniform float spherize_center_x;

//@slider min=0.0 max=1.0 value=0.5
uniform float spherize_center_y;

//@slider min=-3.14 max=3.14 value=0.0
uniform float spherize_3d_rot_x;

//@slider min=-3.14 max=3.14 value=0.0
uniform float spherize_3d_rot_y;

//@slidervec2 min=0.0 max=1.0 value=0.7,0.7
uniform vec2 spherize_light_dir;

//@slider min=0.0 max=2.0 value=0.5
uniform float spherize_highlight;

uniform sampler2D in;

vec3 calculateLighting(vec3 normal, vec2 light_dir, float highlight) {
    vec3 light = normalize(vec3(light_dir, 1.0));
    float diff = max(dot(normal, light), 0.0);
    float ambient = 0.3;

    // Specular highlight
    vec3 view_dir = vec3(0.0, 0.0, 1.0);
    vec3 half_dir = normalize(light + view_dir);
    float spec = pow(max(dot(normal, half_dir), 0.0), 32.0);

    return vec3(ambient + diff * 0.7 + spec * highlight);
}

void main() {
    vec2 uv = v_uv;

    // Calculate offset from center
    vec2 center = vec2(spherize_center_x, spherize_center_y);
    vec2 offset = uv - center;
    float dist = length(offset);

    // Normalize distance
    float norm_dist = dist / (spherize_radius * 2.0);
    norm_dist = clamp(norm_dist, 0.0, 1.0);

    // Spherize displacement
    float displacement = 0.0;
    if (norm_dist <= 1.0) {
        // Sphere displacement formula
        displacement = sin(norm_dist * 3.14159265 * 0.5) * spherize_strength;
    }

    // Apply displacement
    vec2 new_uv;
    if (dist > 0.001) {
        new_uv = center + normalize(offset) * dist * (1.0 + displacement);
    } else {
        new_uv = center;
    }

    // Apply 3D rotation to UV
    float cx = cos(spherize_3d_rot_x);
    float sx = sin(spherize_3d_rot_x);
    float cy = cos(spherize_3d_rot_y);
    float sy = sin(spherize_3d_rot_y);

    // Simple 2D rotation approximation
    vec2 rotated_uv;
    rotated_uv.x = new_uv.x;
    rotated_uv.y = new_uv.y;

    // Sample texture
    vec4 color;
    if (rotated_uv.x >= 0.0 && rotated_uv.x <= 1.0 && rotated_uv.y >= 0.0 && rotated_uv.y <= 1.0) {
        color = texture(in, rotated_uv);
    } else {
        color = vec4(0.0);
    }

    // Calculate fake 3D normal for lighting
    vec2 dx = vec2(0.001, 0.0);
    vec2 dy = vec2(0.0, 0.001);

    vec2 new_uv_x;
    vec2 new_uv_y;

    if (dist > 0.001) {
        new_uv_x = center + normalize(offset + dx) * length(offset + dx) * (1.0 + displacement);
        new_uv_y = center + normalize(offset + dy) * length(offset + dy) * (1.0 + displacement);
    } else {
        new_uv_x = center + dx;
        new_uv_y = center + dy;
    }

    // Calculate normal from UV displacement
    vec2 duv_x = new_uv_x - new_uv;
    vec2 duv_y = new_uv_y - new_uv;

    vec3 normal;
    normal.x = duv_y.y;
    normal.y = -duv_y.x;
    normal.z = duv_x.x * duv_y.y - duv_x.y * duv_y.x;
    normal = normalize(normal);

    // Apply lighting
    float lighting = calculateLighting(normal, spherize_light_dir, spherize_highlight);

    color.rgb *= lighting;

    fragColor = color;
}
